template.xpath:
.designs { display:grid; grid-template-columns:repeat(2, 1fr); gap:10px; }
.design { display:block; position:relative; font-weight:700; font-size:14px; }
.design input { position:absolute; opacity:0; width:auto; }
.design .frame { display:block; border:2px solid var(--line); border-radius:6px; padding:6px; background:#fff; height:100%; color:var(--ink); }
.design img { display:block; width:100%; aspect-ratio:210 / 297; background:var(--paper); margin-bottom:6px; }
.design small { display:block; font-weight:400; font-size:13px; line-height:1.3; color:var(--muted); }
.design input:checked + .frame { border-color:var(--navy); box-shadow:0 0 0 2px var(--hivis); }
.design input:focus-visible + .frame { outline:3px solid var(--navy); outline-offset:2px; }
